Yes, it is common to have a separate presale contract for early investors. This would allow you to set different parameters for the presale such as the price, time limit, and the amount of tokens that can be purchased per wallet. It also allows you to control the distribution of tokens before the main launch.

On the other hand, the main contract would handle the public sale or launchpad sale. You can then transfer the tokens from the presale contract to the main contract once the presale is over.

Here's a simple example of how you might structure these two different contracts in Solidity:

``` solidity
// Presale contract
contract Presale {
    address public owner;
    uint public tokenPrice;
    uint public tokensSold;
    address public tokenAddress;
    bool public isSaleActive;

    constructor(address _tokenAddress, uint _tokenPrice) {
        owner = msg.sender;
        tokenAddress = _tokenAddress;
        tokenPrice = _tokenPrice;
        isSaleActive = false;
    }

    function startSale() public {
        require(msg.sender == owner, "Only owner can start the sale.");
        isSaleActive = true;
    }

    function buyTokens(uint _numberOfTokens) public {
        require(isSaleActive, "Sale is not active.");
        require(msg.value == _numberOfTokens * tokenPrice, "Insufficient Ether.");
        require(_numberOfTokens > 0, "Invalid number of tokens.");

        // Transfer tokens to the buyer
        Token token = Token(tokenAddress);
        token.transfer(msg.sender, _numberOfTokens);

        tokensSold += _numberOfTokens;
    }
}

// Main contract
contract MainSale {
    address public owner;
    uint public tokenPrice;
    uint public tokensSold;
    address public tokenAddress;
    bool public isSaleActive;

    constructor(address _tokenAddress, uint _tokenPrice) {
        owner = msg.sender;
        tokenAddress = _tokenAddress;
        tokenPrice = _tokenPrice;
        isSaleActive = false;
    }

    function startSale() public {
        require(msg.sender == owner, "Only owner can start the sale.");
        isSaleActive = true;
    }

    function buyTokens(uint _numberOfTokens) public {
        require(isSaleActive, "Sale is not active.");
        require(msg.value == _numberOfTokens * tokenPrice, "Insufficient Ether.");
        require(_numberOfTokens > 0, "Invalid number of tokens.");

        // Transfer tokens to the buyer
        Token token = Token(tokenAddress);
        token.transfer(msg.sender, _numberOfTokens);

        tokensSold += _numberOfTokens;
    }
}
```

Please note that the above code is for illustration purposes only. In a real-world scenario, you should consider more factors such as token limits, wallet limits, liquidity pool, etc. Also, you may want to use a token standard like ERC20 or ERC721.<|im_end|>

TypeScript is a statically typed programming language that is a superset of JavaScript. It adds optional static typing to JavaScript, allowing developers to define types for variables, parameters, and return values. TypeScript is compiled to JavaScript, which means that TypeScript code can be run in any browser that supports JavaScript.

Duck typing is a concept of dynamic typing in programming languages where the type of an object is determined by its behavior rather than its declared type. In duck typing, if an object has all the properties and methods of a particular type, then it is considered to be of that type, even if it is not explicitly declared as such. Duck typing is commonly used in dynamically typed languages like Python and Ruby.

Here's an example of TypeScript code that uses duck typing:

```
interface Animal {
  move(): void;
}

class Dog implements Animal {
  move() {
    console.log("Dog is moving");
  }
}

class Cat implements Animal {
  move() {
    console.log("Cat is moving");
  }
}

function moveAnimal(animal: Animal) {
  animal.move();
}

let dog = new Dog();
let cat = new Cat();

moveAnimal(dog); // Output: Dog is moving
moveAnimal(cat); // Output: Cat is moving
```

In this example, we define an interface `Animal` that has a method `move()`. We then define two classes `Dog` and `Cat` that implement the `Animal` interface. Finally, we define a function `moveAnimal()` that takes an `Animal` object as a parameter and calls its `move()` method.

When we call `moveAnimal()` with a `Dog` object or a `Cat` object, TypeScript checks that both objects implement the `Animal` interface and have a `move()` method. This is an example of duck typing, where we don't care about the specific type of the object, but rather that it has the required properties and methods.<|im_end|>

Here is a simple example of how to create a Discord bot with a ban command using Discord.js v14. Please note that you should replace "YOUR_BOT_TOKEN" with your actual bot token.

```javascript
const { Client, GatewayIntentBits, REST, Routes } = require('discord.js');
const { clientId, guildId, token } = require('./config.json');

const client = new Client({ intents: [GatewayIntentBits.Guilds] });
const commands = [];

const commandData = {
    name: 'ban',
    description: 'Ban a user',
    options: [
        {
            name: 'user',
            description: 'The user to ban',
            type: 6,
            required: true,
        },
        {
            name: 'reason',
            description: 'The reason for the ban',
            type: 3,
            required: false,
        },
    ],
};

commands.push(commandData);

const rest = new REST().setToken(token);

(async () => {
    try {
        console.log('Started refreshing application (/) commands.');

        await rest.put(
            Routes.applicationGuildCommandsId(clientId, guildId),
            { body: commands },
        );

        console.log('Successfully reloaded application (/) commands.');
    } catch (error) {
        console.error(error);
    }
})();

client.on('ready', () => {
    console.log(`Logged in as ${client.user.tag}!});

client.on('interactionCreate', async interaction => {
    if (!interaction.isCommand()) return;

    const { commandName, options } = interaction;

    if (commandName === 'ban') {
        const user = options.getUser('user');
        const reason = options.getString('reason');

        await interaction.guild.members.ban(user.id, reason);
        await interaction.reply(`Banned ${user.tag} for ${reason || 'no reason'}.`);
    }
});

client.login('YOUR_BOT_TOKEN');
```

This code creates a Discord bot that listens for slash commands. When a user uses the "ban" command, the bot will ban the specified user from the server. The bot will also include the reason for the ban in the reply message.

Please note that this is a basic example and does not include error handling or permissions checking. You should add these features to your bot to make it more robust and secure.<|im_end|>

Here is a basic C++ function that converts Markdown formatted text to HTML formatted text. Note that this is a very simple implementation and it does not cover all possible Markdown syntaxes. For a full-featured Markdown to HTML converter, you may want to use a library such as libmarkdown or CommonMark.

```cpp
#include <string>
#include <cctype>

std::string markdownToHtml(const std::string& markdown) {
    std::string html = "";
    bool inItalic = false;
    bool inBold = false;

    for (char& c : markdown) {
        if (c == '_') {
            if (!inItalic) {
                html += "<i>";
                inItalic = true;
            } else {
                html += "</i>";
                inItalic = false;
            }
        } else if (c == '*') {
            if (!inBold) {
                html += "<b>";
                inBold = true;
            } else {
                html += "</b>";
                inBold = false;
            }
        } else {
            html += c;
        }
    }

    return html;
}
```

This function converts underscore (_)_ to `<i>` and `</i>` tags for italic text, and asterisks (*) to `<b>` and `</b>` tags for bold text. It does not handle headers, lists, links, etc. If you want to handle all Markdown syntaxes, you will need to use a more sophisticated library or write a more complex function.<|im_end|>

Creating a snake game in C with images can be a complex task. You would need to use a library like SDL (Simple DirectMedia Layer) to handle graphics, animations, and events. Here's a basic outline of how you could go about creating this game:

1. Install SDL Library: You need to install the SDL library on your system. You can download it from the official website: https://www.libsdl.org/download-2.0.php

2. Create the Window: Use the SDL library to create a window where the game will be displayed.

3. Load Images: Load the images that you want to use for the snake, food, and background. You can use the IMG_LoadBMP() function from the SDL_image library to load images.

4. Create Snake: Create the snake using the loaded image. You can create a snake by drawing a series of images in a line.

5. Create Food: Create the food using the loaded image. You can create the food by drawing the image at a random position on the screen.

6. Handle Events: Handle the events such as key presses, mouse clicks, etc.

7. Animation: Move the snake by updating its position and drawing the snake at the new position. You can use a timer to control the speed of the snake.

8. Collision Detection: Check for collisions between the snake and the food, the snake and the walls, and the snake and itself.

Here's a simple code snippet to get you started:

```c
#include <SDL2/SDL.h>
#include <SDL2/SDL_image.h>
#include <stdio.h>

#define SCREEN_WIDTH 640
#define SCREEN_HEIGHT 480

int main(int argc, char *argv[]) {
    // Initialize SDL
    SDL_Init(SDL_INIT_VIDEO);

    // Create the window
    SDL_Window *window = SDL_CreateWindow("Snake Game", SDL_WINDOWPOS_UNDEFINED, SDL_WINDOWPOS_UNDEFINED, SCREEN_WIDTH, SCREEN_HEIGHT, SDL_WINDOW_SHOWN);

    // Create the renderer
    SDL_Renderer *renderer = SDL_CreateRenderer(window, -1, 0);

    // Load the images
    SDL_Surface *snake_surface = IMG_Load("snake.bmp");
    SDL_Surface *food_surface = IMG_Load("food.bmp");
    SDL_Texture *snake_texture = SDL_CreateTextureFromSurface(renderer, snake_surface);
    SDL_Texture *food_texture = SDL_CreateTextureFromSurface(renderer, food_surface);

    // Create the snake
    SDL_Rect snake_rect = {10, 10, snake_surface->w_width, snake_surface->w_height};

    // Create the food
    SDL_Rect food_rect = {200, 200, food_surface->w_width, food_surface->w_height};

    // Handle events
    SDL_Event event;

    // Animation
    int quit = 0;
    while (!quit) {
        // Handle events
        while (SDL_PollEvent(&event)) {
            if (event.type == SDL_QUIT) {
                quit = 1;
            }
        }

        // Clear the renderer
        SDL_SetRenderDrawColor(renderer, 0, 0, 0, 255);
        SDL_RenderClear(renderer);

        // Draw the snake
        SDL_RenderCopy(renderer, snake_texture, NULL, &snake_rect);

        // Draw the food
        SDL_RenderCopy(renderer, food_texture, NULL, &food_rect);

        // Update the renderer
        SDL_RenderPresent(renderer);
    }

    // Clean up
    SDL_DestroyTexture(snake_texture);
    SDL_DestroyTexture(food_texture);
    SDL_DestroyRenderer(renderer);
    SDL_DestroyWindow(window);
    SDL_Quit();

    return 0;
}
```

This is just a basic outline of how you can create a snake game in C with images. You will need to add more code to handle events, animation, and collision detection.<|im_end|>

